CREATE TABLE p(id INTEGER PRIMARY KEY, k INT, v INT, s TEXT);
CREATE TABLE q(id INTEGER PRIMARY KEY, k INT, v INT, s TEXT COLLATE NOCASE);
CREATE TABLE n(k INT, v INT, s TEXT);
CREATE TABLE e(k INT, v INT, s TEXT);
CREATE TABLE f(k INT, v INT, s TEXT);
INSERT INTO p VALUES (1, 1, 2, '1'), (2, 2, 3, 'b'), (3, NULL, 1, 'B'), (4, 4, NULL, NULL), (5, 1, 0, '2');
INSERT INTO q VALUES (1, 2, 2, 'B'), (2, 2, 0, 'a'), (3, 5, 1, '1'), (4, NULL, 4, NULL), (5, 1, 1, 'c');
INSERT INTO n VALUES (1, 2, '2'), (NULL, 1, 'b'), (2, 2, NULL), (3, 0, 'A'), (1, NULL, '1');
INSERT INTO f VALUES (1, 2, '2'), (2, 1, 'b'), (2, 5, NULL);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS NOT a2.k;
EXPLAIN QUERY PLAN SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS NOT a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS a2.v;
EXPLAIN QUERY PLAN SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS a2.v;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT count(*) FROM n WHERE n.k = a0.k) = a2.v;
SELECT a0.k, a1.k, a2.k, (SELECT count(*) FROM n WHERE n.k = a0.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v;
EXPLAIN QUERY PLAN SELECT a0.k, a1.k, a2.k, (SELECT count(*) FROM n WHERE n.k = a0.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v;
SELECT a0.k, a1.k, a2.k, (SELECT count(*) FROM n WHERE n.k = a0.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v;
SELECT count(*), sum(a2.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS NOT a2.k;
SELECT count(*), sum(a2.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) = a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a2.k IS NULL OR EXISTS (SELECT 1 FROM n WHERE n.v = a0.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v ORDER BY (SELECT count(*) FROM n WHERE n.k = a0.k), 1, 2, 3;
SELECT a0.k, count(*) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v GROUP BY (SELECT count(*) FROM n WHERE n.k = a0.k);
SELECT sum((SELECT count(*) FROM n WHERE n.k = a0.k)) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v;
SELECT sum((SELECT count(*) FROM n WHERE n.k = a0.k)) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v;
